type Product = { id: string; name: string; categoryId: string; priceCents: number };
type CatalogueQuestion = {
  invoke(input: { question: string; filter: { categoryId: string }; topK: number }): Promise<{ answer: string }>;
};

export async function answerCategoryQuestion(
  retriever: CatalogueQuestion,
  categoryId: string,
  question: string,
): Promise<string> {
  const result = await retriever.invoke({
    question,
    filter: { categoryId },
    topK: 5,
  });
  return result.answer;
}

